import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"glossary.md","filePath":"glossary.md"}`),a={name:`glossary.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to “Glossary”">​</a></h1><p><a href="/faultdeck/zh/glossary.html">中文术语表</a>。 These terms describe the implemented responsibility layers, not directory names. Architecture sections are in <a href="/faultdeck/architecture.html#source-layer-map">Architecture</a>.</p><table tabindex="0"><thead><tr><th>术语</th><th>English</th><th>定义</th><th>file:line</th></tr></thead><tbody><tr><td>故障规格</td><td><code>FaultSpec</code></td><td>A tagged model for latency, loss, or disconnect semantics shared by the user boundary, coordinator, agent, and adapters.</td><td><code>crates/core/src/lib.rs:26</code></td></tr><tr><td>故障目标</td><td><code>Target</code></td><td>The optional IPv4 source, destination, and destination-port selectors that scope one injection.</td><td><code>crates/core/src/lib.rs:44</code></td></tr><tr><td>注入请求</td><td><code>Injection</code></td><td>One fault plus one target; this pair is the shared execution contract.</td><td><code>crates/core/src/lib.rs:82</code></td></tr><tr><td>内在校验</td><td>intrinsic validation</td><td>Checks fault ranges, non-empty targets, and IPv6 support before backend-specific behavior runs.</td><td><code>crates/core/src/lib.rs:108</code></td></tr><tr><td>管理网段保护</td><td>management-network protection</td><td>Rejects a target whose networks overlap operator-provided protected CIDRs.</td><td><code>crates/core/src/lib.rs:142</code></td></tr><tr><td>执行器端口</td><td><code>CommandExecutor</code></td><td>The netem adapter&#39;s boundary for running or recording <code>tc</code> commands; production and test executors implement it.</td><td><code>crates/netem/src/lib.rs:73</code></td></tr><tr><td>tc 命令</td><td><code>TcCommand</code></td><td>A reproducible program-and-arguments representation of one traffic-control operation.</td><td><code>crates/netem/src/lib.rs:56</code></td></tr><tr><td>netem 适配器</td><td><code>NetemAdapter</code></td><td>Plans, applies, and rolls back qdisc/filter state for latency and loss on one interface.</td><td><code>crates/netem/src/lib.rs:172</code></td></tr><tr><td>pilot qdisc</td><td>pilot qdisc</td><td>FaultDeck-owned root qdisc handle <code>100:</code> used to recognize and safely remove only its own traffic-control state.</td><td><code>crates/netem/src/lib.rs:13</code></td></tr><tr><td>断连路由</td><td>disconnect routing</td><td>The agent routes a disconnect injection to iptables instead of <code>tc</code>; other faults go to netem.</td><td><code>crates/agent/src/lib.rs:196</code></td></tr><tr><td>iptables 链</td><td>iptables chain</td><td>The <code>FAULTDECK</code> mangle chain and its <code>INPUT</code> jump carry disconnect DROP rules.</td><td><code>crates/agent/src/firewall.rs:9</code></td></tr><tr><td>断连适配器</td><td>disconnect adapter</td><td><code>Iptables</code> ensures the chain, installs DROP rules, and performs idempotent rollback.</td><td><code>crates/agent/src/firewall.rs:31</code></td></tr><tr><td>Agent 配置</td><td><code>AgentConfig</code></td><td>Process-start settings: bind address, optional token, target interface, and management networks.</td><td><code>crates/agent/src/lib.rs:90</code></td></tr><tr><td>单活动故障</td><td>single active fault</td><td>Agent-host state that rejects a second injection until rollback clears the adapter marker.</td><td><code>crates/agent/src/lib.rs:191</code></td></tr><tr><td>Agent 线请求</td><td>agent wire request</td><td>The tagged <code>ping</code>, <code>inject</code>, or <code>rollback</code> payload decoded by the agent host.</td><td><code>crates/agent/src/lib.rs:109</code></td></tr><tr><td>Agent 线响应</td><td>agent wire response</td><td>The tagged <code>ok</code> or <code>error</code> result returned to the CLI.</td><td><code>crates/agent/src/lib.rs:117</code></td></tr><tr><td>令牌鉴权</td><td>token authentication</td><td>Optional shared-secret comparison at each process boundary; an unset token means auth is disabled.</td><td><code>crates/agent/src/lib.rs:124</code></td></tr><tr><td>NDJSON 帧</td><td>NDJSON frame</td><td>A newline-delimited JSON value with a hard 64 KiB frame ceiling.</td><td><code>crates/agent/src/transport.rs:56</code></td></tr><tr><td>Mode A</td><td>Mode A</td><td>Agent-listens topology: the controller opens one TCP stream to the resident target agent.</td><td><code>crates/agent/src/transport.rs:94</code></td></tr><tr><td>Mode B</td><td>Mode B</td><td>Controller-listens reverse-connect topology with retry and backoff for NAT traversal.</td><td><code>crates/agent/src/transport.rs:118</code></td></tr><tr><td>中枢信封</td><td><code>WireMessage</code></td><td>The coordinator envelope carrying an optional token and one control command.</td><td><code>crates/coordinator/src/lib.rs:235</code></td></tr><tr><td>中枢命令</td><td><code>AgentCommand</code></td><td>Register, heartbeat, inject, rollback, fetch-report, or list-agents operations accepted by the coordinator.</td><td><code>crates/coordinator/src/lib.rs:69</code></td></tr><tr><td>中枢响应</td><td><code>AgentResponse</code></td><td>Coordinator acknowledgement, queue receipt, registry listing, report, or error result.</td><td><code>crates/coordinator/src/lib.rs:80</code></td></tr><tr><td>Agent 身份</td><td><code>AgentIdentity</code></td><td>An agent ID, capability list, last-seen timestamp, and list-time online flag stored by the coordinator.</td><td><code>crates/coordinator/src/lib.rs:51</code></td></tr><tr><td>心跳</td><td>heartbeat</td><td>Updates one registered agent&#39;s <code>last_seen_ms</code>; freshness feeds the online check.</td><td><code>crates/coordinator/src/lib.rs:178</code></td></tr><tr><td>Agent 链路</td><td>agent link</td><td>The agent&#39;s outbound connection to the coordinator; <code>LinkMessage::Dispatch</code> goes down it, <code>Result</code>/<code>Heartbeat</code> come back up.</td><td><code>crates/coordinator/src/lib.rs:134</code></td></tr><tr><td>在线状态</td><td>online status</td><td>Link liveness OR a heartbeat within <code>HEARTBEAT_TIMEOUT_MS</code> (30 s); offline agents are excluded from <code>available</code>.</td><td><code>crates/coordinator/src/lib.rs:211</code></td></tr><tr><td>指令入队</td><td>queued command</td><td>When the target agent is offline, inject/rollback persist in its queue and are dispatched on its next registration.</td><td><code>crates/coordinator/src/lib.rs:351</code></td></tr><tr><td>场景</td><td><code>Scenario</code></td><td>A named injection whose stable serialization is the input to hashing and reporting.</td><td><code>crates/report/src/lib.rs:38</code></td></tr><tr><td>场景哈希</td><td>scenario hash</td><td>The SHA-256 identity of a scenario, used for report lookup and comparison.</td><td><code>crates/report/src/lib.rs:49</code></td></tr><tr><td>运行报告</td><td><code>RunReport</code></td><td>The canonical result model containing scenario identity, timestamps, evidence, and replay text.</td><td><code>crates/report/src/lib.rs:78</code></td></tr><tr><td>回放命令</td><td>replay command</td><td>A shell-quoted CLI invocation generated by the user boundary and stored in the report.</td><td><code>crates/cli/src/main.rs:315</code></td></tr><tr><td>恢复证据</td><td>restore evidence</td><td>A timestamped post-rollback check with pass/fail and detail fields.</td><td><code>crates/report/src/lib.rs:63</code></td></tr><tr><td>外部断言</td><td>external assertion</td><td>A named externally observed result attached to a run report.</td><td><code>crates/report/src/lib.rs:71</code></td></tr><tr><td>历史 diff</td><td>historical diff</td><td>A structural comparison of two reports&#39; event, evidence, and assertion collections.</td><td><code>crates/report/src/lib.rs:175</code></td></tr></tbody></table>`,3)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};